const body = $input.item.json.body || $input.item.json;
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const tiposValidos = ['reporte.creado', 'reporte.estado_cambiado', 'n8n.flujo_fallido', 'modelo.deriva_detectada'];
const franjasValidas = ['mañana', 'tarde', 'noche'];
const estadosValidos = ['Pendiente', 'En Proceso', 'Resuelto'];

let esValido = true;
let errorDetalle = '';

if (!body.id || !uuidRegex.test(body.id)) {
  esValido = false;
  errorDetalle = 'El campo "id" debe ser un UUID v4 válido.';
} else if (!body.tipo || !tiposValidos.includes(body.tipo)) {
  esValido = false;
  errorDetalle = `El campo "tipo" debe ser uno de: ${tiposValidos.join(', ')}.`;
} else if (!body.fecha || isNaN(Date.parse(body.fecha))) {
  esValido = false;
  errorDetalle = 'El campo "fecha" debe ser un ISO 8601 válido.';
} else if (!body.origen || typeof body.origen !== 'string') {
  esValido = false;
  errorDetalle = 'El campo "origen" es obligatorio.';
} else if (!body.datos || typeof body.datos !== 'object') {
  esValido = false;
  errorDetalle = 'El campo "datos" debe ser un objeto JSON.';
} else {
  const d = body.datos;
  if (body.tipo === 'reporte.creado') {
    if (!d.reporte_id || !d.distrito || !franjasValidas.includes(d.franja) || !d.tipo_incidente) {
      esValido = false;
      errorDetalle = 'Campos de reporte.creado requeridos: reporte_id, distrito, franja (mañana|tarde|noche), tipo_incidente.';
    }
  } else if (body.tipo === 'reporte.estado_cambiado') {
    if (!d.reporte_id || !estadosValidos.includes(d.estado_anterior) || !estadosValidos.includes(d.estado_nuevo)) {
      esValido = false;
      errorDetalle = 'Campos de reporte.estado_cambiado requeridos: reporte_id, estado_anterior, estado_nuevo.';
    }
  } else if (body.tipo === 'n8n.flujo_fallido') {
    if (!d.workflow_id || !d.workflow_nombre || !d.ejecucion_id || !d.mensaje_error) {
      esValido = false;
      errorDetalle = 'Campos de n8n.flujo_fallido requeridos: workflow_id, workflow_nombre, ejecucion_id, mensaje_error.';
    }
  } else if (body.tipo === 'modelo.deriva_detectada') {
    if (!d.modelo || d.version === undefined || d.psi_max === undefined || d.f1_real === undefined || !d.reporte_url) {
      esValido = false;
      errorDetalle = 'Campos de modelo.deriva_detectada requeridos: modelo, version, psi_max, f1_real, reporte_url.';
    }
  }
}

return [{
  json: {
    es_valido: esValido,
    http_code: esValido ? 202 : 400,
    response_body: esValido
      ? { estado: 'recibido', id: body.id, tipo: body.tipo, timestamp: new Date().toISOString() }
      : { error: 'Validación de sobre o datos fallida', detalle: errorDetalle },
    evento: body
  }
}];

